<template>
  <section class="marketing-rewards" aria-labelledby="consumption-admin-title">
    <header class="page-intro"><div><h2 id="consumption-admin-title" style="font-size:24px">{{ visual.title }}</h2><p class="intro-copy">{{ visual.intro }}</p></div><button type="button" class="action-secondary" :disabled="busy" @click="newDraft">＋ {{ labels.newCampaign }}</button></header>
    <ActivityAudience kind="consumption" />
    <nav v-if="campaigns.length" class="campaign-tabs" :aria-label="labels.title">
      <button v-if="!draft.id" type="button" class="campaign-tab selected" aria-current="true" :disabled="busy"><span>{{ visual.empty }}</span><span class="campaign-tab-state">{{ labels.states.draft }}</span></button>
      <button v-for="item in campaigns" :key="item.id" type="button" class="campaign-tab" :class="{selected:draft.id===item.id}" :aria-current="draft.id===item.id?'true':undefined" :disabled="busy" @click="select(item)"><span class="campaign-tab-name" :title="item.name">{{ item.name }}</span><span class="campaign-tab-state" :class="{'is-active':item.state==='active'}">{{ labels.states[item.state as 'draft'|'active'|'paused'|'closed'] || item.state }}</span></button>
    </nav>
    <p v-else class="campaign-empty-state"><span aria-hidden="true"></span>{{ visual.draft }}</p>
    <section class="tier-story" :aria-label="visual.path"><div class="tier-story-heading"><div><h2>{{ visual.path }}</h2><p>{{ visual.unit }}</p></div><div class="total-reward"><span>{{ visual.total }}</span><strong>${{ dollar(rewardTotal) }}</strong></div></div><div class="tier-track"><div v-for="tier in draft.tiers" :key="tier.position" class="tier-stop"><span class="tier-index">{{ locale.startsWith('zh') ? `第 ${tier.position} 档` : `Tier ${tier.position}` }}</span><span class="tier-node" aria-hidden="true">{{ tier.position }}</span><span class="tier-condition">{{ labels.validSpend }} <b>${{ dollar(tier.threshold_cents) }}</b></span><div class="tier-value"><span>{{ visual.paid }}</span><strong>${{ dollar(tier.reward_cents) }}</strong></div></div></div><div class="tier-story-foot">{{ labels.rules }}</div></section>
    <div v-if="selected" class="metrics-row"><div class="metric"><span>{{ labels.reserved }}</span><strong>${{ dollar(selected.reserved_cents/100) }}</strong></div><div class="metric"><span>{{ labels.claimed }}</span><strong>${{ dollar(selected.claimed_cents/100) }}</strong></div><div class="metric"><span>{{ labels.participants }}</span><strong>{{ selected.participants }}</strong></div><div class="metric"><span>{{ labels.qualified }}</span><strong>{{ selected.qualified_users }}</strong></div></div>
    <form @submit.prevent="save">
      <div class="workspace-grid">
        <section class="config-surface"><div class="surface-title"><div><h2>{{ visual.settings }}</h2><p>{{ published?visual.freeze:visual.draft }}</p></div></div>
          <section class="section-group"><h3>{{ visual.schedule }}</h3><div class="field-grid"><label class="input-label full-width">{{ labels.name }}<input v-model="draft.name" name="campaign_name" class="input" :disabled="published" required maxlength="100"></label><label v-for="field in timeFields" :key="field" class="input-label">{{ labels[field] }}<input v-model="draft[field]" :name="field" type="datetime-local" class="input" :disabled="published" required><span class="mt-1 block text-xs font-normal text-gray-500 dark:text-gray-400">{{ labels.timezone }}</span></label></div></section>
          <section class="section-group"><h3>{{ visual.tiers }}</h3><div class="tier-editor-heading"><span>{{ labels.tier }}</span><span>{{ labels.threshold }}</span><span>{{ labels.reward }}</span></div><div v-for="tier in draft.tiers" :key="tier.position" class="tier-editor-row"><span class="editor-tier"><b>{{ tier.position }}</b>{{ labels.tier }}</span><label class="input-unit"><span aria-hidden="true">$</span><input v-model.number="tier.threshold_cents" :name="`threshold_${tier.position}`" :aria-label="`${labels.tier} ${tier.position} ${labels.threshold}`" type="number" min="0.01" step="0.01" :disabled="published" required></label><label class="input-unit reward-input"><span aria-hidden="true">$</span><input v-model.number="tier.reward_cents" :name="`reward_${tier.position}`" :aria-label="`${labels.tier} ${tier.position} ${labels.reward}`" type="number" min="0.01" step="0.01" :disabled="published" required></label></div><p class="section-copy">{{ visual.freeze }}</p></section>
          <div class="section-group"><p class="section-copy">{{ labels.publishHelp }}</p></div>
        </section>
        <aside class="budget-panel"><div class="surface-title"><h2>{{ visual.budget }}</h2></div><div class="field"><div><label for="campaign-budget">{{ labels.budget }}</label><RewardFieldTip :label="labels.budget" :text="labels.budgetHelp" /></div><div class="input-unit budget-input"><span aria-hidden="true">$</span><input id="campaign-budget" v-model.number="draft.budget_cents" name="budget" type="number" min="0.01" step="0.01" aria-describedby="campaign-budget-help" required></div><small id="campaign-budget-help">{{ labels.budgetHelp }}</small></div><div class="field"><label for="campaign-coverage">{{ labels.coverage }}</label><div class="input-unit suffix"><span aria-hidden="true">%</span><input id="campaign-coverage" v-model.number="draft.rollout_percent" name="coverage" type="number" min="1" max="100" step="1" :disabled="published" required></div></div><div class="coverage-visual" aria-hidden="true"><span v-for="n in 10" :key="n" :class="{filled:n<=Math.ceil(Number(draft.rollout_percent)/10)}"></span></div><RouterLink to="/operations/rewards/checkin" class="budget-link">{{ visual.shared }} <span aria-hidden="true">↗</span></RouterLink><div class="inline-note">{{ visual.freeze }}</div></aside>
      </div>
      <div class="configuration-footer"><p>{{ visual.unit }}</p><div class="flex flex-wrap gap-3"><button type="submit" class="action-primary" :disabled="busy">{{ published?labels.saveBudget:labels.saveDraft }}</button><button v-if="draft.id&&!published" type="button" class="action-secondary" :disabled="busy" @click="changeState('active')">{{ labels.publish }}</button><button v-if="selected?.state==='active'" type="button" class="action-secondary" :disabled="busy" @click="changeState('paused')">{{ labels.pause }}</button><button v-if="published&&selected?.state!=='closed'" type="button" class="action-secondary" :disabled="busy" @click="changeState('closed')">{{ labels.close }}</button></div></div>
    </form>
    <p v-if="message" class="reward-status" :class="failed?'text-red-600 dark:text-red-400':'text-emerald-700 dark:text-emerald-300'" role="status">{{ message }}</p>
    <details class="accounting-panel"><summary class="cursor-pointer text-sm font-semibold text-gray-800 dark:text-dark-100">{{ labels.accounting }}</summary><p class="mt-3 text-xs leading-relaxed text-gray-500">{{ labels.accountingHelp }}</p>
      <form class="mt-4 flex flex-wrap items-end gap-3" @submit.prevent="loadFunds"><label class="input-label">{{ labels.userID }}<input v-model.number="userID" type="number" min="1" step="1" class="input mt-1" required></label><button class="btn btn-secondary" :disabled="busy">{{ labels.lookup }}</button></form>
      <template v-if="funds"><p class="mt-4 text-sm text-gray-700 dark:text-dark-200">{{ labels.principal }} ${{ funds.status.funds.principal }} · {{ labels.gift }} ${{ funds.status.funds.gift }} · {{ labels.unverified }} ${{ funds.status.funds.unverified }}</p>
        <form class="mt-4 grid items-end gap-3 sm:grid-cols-4" @submit.prevent="reconcile"><label class="input-label">{{ labels.amount }}<input v-model="confirmation.amount" type="number" min="0.00000001" step="0.00000001" class="input mt-1" required></label><label class="input-label">{{ labels.source }}<select v-model="confirmation.source" class="input mt-1"><option value="principal">{{ labels.principal }}</option><option value="gift">{{ labels.gift }}</option></select></label><label class="input-label">{{ labels.note }}<input v-model="confirmation.note" class="input mt-1" required></label><button class="btn btn-secondary" :disabled="busy">{{ labels.confirmSource }}</button></form>
        <div class="mt-4 overflow-x-auto"><table class="w-full text-left text-xs text-gray-600 dark:text-dark-300"><thead><tr><th class="p-2">ID / {{ labels.source }}</th><th class="p-2">{{ labels.principal }}</th><th class="p-2">{{ labels.gift }}</th><th class="p-2">{{ labels.unverified }}</th><th class="p-2">{{ labels.validSpend }}</th><th class="p-2">{{ labels.note }}</th></tr></thead><tbody><tr v-for="row in funds.ledger" :key="row.id" class="border-t border-gray-100 dark:border-dark-700"><td class="p-2">{{ row.id }} / {{ row.source }}</td><td class="p-2">{{ row.principal }}</td><td class="p-2">{{ row.gift }}</td><td class="p-2">{{ row.unverified }}</td><td class="p-2">{{ row.eligible_cost }}</td><td class="p-2">{{ row.note }}</td></tr></tbody></table></div>
        <form class="mt-4 flex flex-wrap items-end gap-3" @submit.prevent="correct"><label class="input-label">{{ labels.ledgerID }}<input v-model.number="correction.id" type="number" min="1" class="input mt-1" required></label><label class="input-label">{{ labels.note }}<input v-model="correction.note" class="input mt-1" required></label><button class="btn btn-secondary" :disabled="busy">{{ labels.correct }}</button></form>
        <form class="mt-4 flex flex-wrap items-end gap-3" @submit.prevent="resolveReview"><label class="input-label">{{ labels.decision }}<select v-model="review.approve" class="input mt-1"><option :value="true">{{ labels.approve }}</option><option :value="false">{{ labels.revoke }}</option></select></label><label class="input-label">{{ labels.note }}<input v-model="review.note" class="input mt-1" required></label><button class="btn btn-secondary" :disabled="busy">{{ labels.resolve }}</button></form>
      </template>
    </details>
    <details class="accounting-panel"><summary class="cursor-pointer text-sm text-gray-700 dark:text-dark-200" @click="loadAudit">{{ labels.audit }}</summary><ul class="mt-3 space-y-2 text-xs text-gray-500"><li v-for="item in audit" :key="item.id">{{ item.created_at }} · #{{ item.actor_id }} · {{ item.action }} · #{{ item.target_id }} · {{ item.detail }}</li></ul></details>
  </section>
</template>
<script setup lang="ts">
import ActivityAudience from './ActivityAudience.vue'
import {computed,onMounted,ref} from 'vue'
import {useI18n} from 'vue-i18n'
import {consumptionAPI,type ConsumptionCampaign} from '@/api/consumption'
import RewardFieldTip from './RewardFieldTip.vue'
import {extractApiErrorMessage} from '@/utils/apiError'
const {locale}=useI18n()
const zh={title:'消费阶梯奖励',intro:'替代二次充值权益；先保存草稿并核对账务，再发布活动。',newCampaign:'新建一期',name:'活动名称',starts_at:'开始时间',ends_at:'结束时间',claim_until:'领取截止时间',timezone:'北京时间（UTC+8）',coverage:'参与比例（%）',budget:'本期预算（美元）',budgetHelp:'包含已预留与已领取，不按月重置；发布后只能调高。',tier:'档位',threshold:'累计有效消费门槛（美元）',reward:'本档奖励（美元）',rules:'仅计本金支付的已结算 API 消费；赠额、订阅和 Cyber 不计入。每档每人每期一次。已达标未领取奖励会占用预算。',publishHelp:'正式开始前发布，发布后锁定时间与档位。暂停后不再累计，不支持恢复，请新建下一期；已预留奖励仍可领到截止时间。共用预算须覆盖本期预算，个人累计上限须覆盖全部档位，签到也占用这两项额度。',reserved:'已预留',claimed:'已发放',participants:'有效消费人数',qualified:'达标人数',saveBudget:'保存预算',saveDraft:'保存草稿',publish:'发布活动',pause:'暂停新增奖励',close:'结束活动',accounting:'历史余额确认与消费审计',accountingHelp:'历史余额默认待确认，不影响用户总可用余额。核实凭证后将待确认余额归为本金或赠额；此操作不补算历史消费。消费冲正只撤销对应结算的活动进度，不自动修改账户余额；已发奖励须人工处理。审核操作请先查看用户全部退款和冲正情况，结论会应用到此用户所有待审奖励。',userID:'用户 ID',lookup:'查询余额与流水',principal:'本金',gift:'赠额',unverified:'待确认',amount:'确认金额（美元）',source:'来源',note:'凭证或处理原因（必填）',confirmSource:'确认资金来源',validSpend:'有效消费',ledgerID:'待冲正结算流水 ID',correct:'撤销该笔活动进度',decision:'审核结论',approve:'保留未领资格',revoke:'撤销未领资格',resolve:'记录审核结论',audit:'最近 100 条活动操作记录',saved:'已保存',failed:'操作失败，请重试',precision:'金额最多两位小数，门槛与奖励必须为正数。',states:{draft:'草稿',active:'已发布',paused:'已暂停',closed:'已结束'}}
const en={title:'Consumption milestones',intro:'Replaces second recharge rewards. Verify fund sources before publishing.',newCampaign:'New campaign',name:'Campaign name',starts_at:'Starts',ends_at:'Ends',claim_until:'Claim deadline',timezone:'Beijing time (UTC+8)',coverage:'Coverage (%)',budget:'Campaign budget (USD)',budgetHelp:'Includes reserved and paid rewards; no monthly reset. Only increases after publication.',tier:'Tier',threshold:'Eligible spend threshold (USD)',reward:'This tier reward (USD)',rules:'Only settled principal-funded API usage counts. Gifts, subscriptions and Cyber do not count. Each tier is paid once per user per campaign. Reserved rewards occupy budget.',publishHelp:'Publish before the start. Dates and tiers freeze at publication. Pausing stops new progress and cannot resume; create another campaign. Reserved rewards remain claimable until the deadline. Shared budget must cover this campaign, user lifetime cap must cover all tiers; check-in also uses these limits.',reserved:'Reserved',claimed:'Paid',participants:'Spending users',qualified:'Qualified users',saveBudget:'Save budget',saveDraft:'Save draft',publish:'Publish',pause:'Pause new rewards',close:'End campaign',accounting:'Opening funds and settlement review',accountingHelp:'Historical funds remain unverified without changing total balance. Confirm principal or gift from evidence; historical spending is not recalculated. Settlement correction reverses reward progress only, not account balance. Paid rewards require manual handling. Review all refund and correction records first; a decision applies to all pending rewards for this user.',userID:'User ID',lookup:'Look up funds',principal:'Principal',gift:'Gift',unverified:'Unverified',amount:'Amount (USD)',source:'Source',note:'Evidence or reason (required)',confirmSource:'Confirm fund source',validSpend:'Eligible spend',ledgerID:'Settlement ledger ID',correct:'Reverse reward progress',decision:'Review decision',approve:'Keep unclaimed eligibility',revoke:'Revoke unclaimed eligibility',resolve:'Record decision',audit:'Last 100 activity operations',saved:'Saved',failed:'Operation failed. Try again.',precision:'Use positive thresholds and rewards with at most two decimal places.',states:{draft:'Draft',active:'Published',paused:'Paused',closed:'Closed'}}
const visual=computed(()=>locale.value.startsWith('zh')?{title:'把持续消费，变成下一份奖励',intro:'按有效消费逐档解锁，清晰配置每一期活动。',path:'消费奖励路径',total:'每人本期最高可领',settings:'活动设置',schedule:'活动与时间',tiers:'消费档位',budget:'预算与参与',draft:'草稿预览，尚未发布',unit:'所有金额均为美元（USD）',shared:'前往共用预算配置',freeze:'发布后，活动时间、参与比例与奖励档位将锁定。',paid:'奖励',empty:'新建活动'}:{title:'Turn ongoing usage into rewards',intro:'Set a clear path from eligible spend to each reward.',path:'Reward milestones',total:'Maximum reward per user',settings:'Campaign settings',schedule:'Campaign and schedule',tiers:'Spending tiers',budget:'Budget and participation',draft:'Draft preview · unpublished',unit:'All amounts in USD',shared:'Manage shared budget',freeze:'Publication locks dates, coverage and reward tiers.',paid:'Reward',empty:'New campaign'})
const rewardTotal=computed(()=>draft.value.tiers.reduce((sum,t)=>sum+(Number(t.reward_cents)||0),0))
const dollar=(value:number)=>Number.isFinite(Number(value))?Number(value).toFixed(2):'—'
const labels=computed(()=>locale.value.startsWith('zh')?zh:en)
const campaigns=ref<ConsumptionCampaign[]>([]);const busy=ref(false);const failed=ref(false);const message=ref('');const timeFields=['starts_at','ends_at','claim_until'] as const
const localTime=(date:string)=>new Date(Date.parse(date)+8*3600000).toISOString().slice(0,16)
function blank():ConsumptionCampaign{const start=Date.now()+3600000;return {id:0,name:locale.value.startsWith('zh')?'消费阶梯奖励':'Consumption milestones',starts_at:localTime(new Date(start).toISOString()),ends_at:localTime(new Date(start+30*86400000).toISOString()),claim_until:localTime(new Date(start+37*86400000).toISOString()),rollout_percent:10,budget_cents:0,state:'draft',reserved_cents:0,claimed_cents:0,participants:0,qualified_users:0,tiers:[{position:1,threshold_cents:10,reward_cents:0.3},{position:2,threshold_cents:50,reward_cents:1.2},{position:3,threshold_cents:100,reward_cents:2.5}]}}
const draft=ref(blank());const selected=computed(()=>campaigns.value.find(c=>c.id===draft.value.id));const published=computed(()=>!!selected.value?.published_at)
function select(c:ConsumptionCampaign){draft.value={...c,starts_at:localTime(c.starts_at),ends_at:localTime(c.ends_at),claim_until:localTime(c.claim_until),budget_cents:c.budget_cents/100,tiers:c.tiers.map(t=>({...t,threshold_cents:t.threshold_cents/100,reward_cents:t.reward_cents/100}))};message.value=''}
function newDraft(){draft.value=blank();message.value=''}
async function load(){campaigns.value=await consumptionAPI.campaigns()}
async function action(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;message.value='';try{await fn();failed.value=false;message.value=labels.value.saved}catch(e){failed.value=true;message.value=extractApiErrorMessage(e,labels.value.failed)}finally{busy.value=false}}
function cents(v:number){if(!Number.isFinite(v)||Math.abs(v*100-Math.round(v*100))>1e-7)throw new Error(labels.value.precision);return Math.round(v*100)}
async function save(){await action(async()=>{const c={...draft.value,starts_at:new Date(draft.value.starts_at+':00+08:00').toISOString(),ends_at:new Date(draft.value.ends_at+':00+08:00').toISOString(),claim_until:new Date(draft.value.claim_until+':00+08:00').toISOString(),budget_cents:cents(draft.value.budget_cents),tiers:draft.value.tiers.map(t=>({...t,threshold_cents:cents(t.threshold_cents),reward_cents:cents(t.reward_cents)}))};const {id}=await consumptionAPI.save(c);await load();const saved=campaigns.value.find(v=>v.id===id);if(saved)select(saved)})}
async function changeState(state:string){await action(async()=>{await consumptionAPI.state(draft.value.id,state);await load();const c=campaigns.value.find(c=>c.id===draft.value.id);if(c)select(c)})}
const userID=ref<number>();const funds=ref<Awaited<ReturnType<typeof consumptionAPI.funds>>|null>(null);const confirmation=ref({amount:'',source:'principal',note:''});const correction=ref({id:0,note:''});const review=ref({approve:true,note:''});const audit=ref<Record<string,string|number>[]>([])
async function loadFunds(){await action(async()=>{if(userID.value)funds.value=await consumptionAPI.funds(userID.value)})}
async function reconcile(){await action(async()=>{if(!userID.value)return;await consumptionAPI.reconcile(userID.value,confirmation.value.amount,confirmation.value.source,confirmation.value.note);funds.value=await consumptionAPI.funds(userID.value);confirmation.value={amount:'',source:'principal',note:''}})}
async function correct(){await action(async()=>{await consumptionAPI.correct(correction.value.id,correction.value.note);if(userID.value)funds.value=await consumptionAPI.funds(userID.value)})}
async function resolveReview(){await action(async()=>{if(!userID.value)return;await consumptionAPI.review(userID.value,review.value.approve,review.value.note);funds.value=await consumptionAPI.funds(userID.value)})}
async function loadAudit(){try{audit.value=await consumptionAPI.audit()}catch(e){failed.value=true;message.value=extractApiErrorMessage(e,labels.value.failed)}}
onMounted(async()=>{try{await load();if(campaigns.value[0])select(campaigns.value[0])}catch(e){failed.value=true;message.value=extractApiErrorMessage(e,labels.value.failed)}})
</script>

<style scoped src="./marketingRewards.css"></style>
<style src="./marketingRewardsDark.css"></style>
